// static
bool PageStubDispatch::Accept(
    Page* impl,
    mojo::Message* message) {
  switch (static_cast<messages::Page>(message->header()->name)) {
    case messages::Page::kOnRequestCreated: {
      DCHECK(message->is_serialized());
      internal::Page_OnRequestCreated_Params_Data* params =
          reinterpret_cast<internal::Page_OnRequestCreated_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.0
      bool success = true;
      RequestPtr p_request{};
      Page_OnRequestCreated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadRequest(&p_request))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnRequestCreated(        
        std::move(p_request));
      return true;
    }
    case messages::Page::kOnRequestStarted: {
      DCHECK(message->is_serialized());
      internal::Page_OnRequestStarted_Params_Data* params =
          reinterpret_cast<internal::Page_OnRequestStarted_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.1
      bool success = true;
      RequestPtr p_request{};
      Page_OnRequestStarted_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadRequest(&p_request))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnRequestStarted(        
        std::move(p_request));
      return true;
    }
    case messages::Page::kOnRequestCompleted: {
      DCHECK(message->is_serialized());
      internal::Page_OnRequestCompleted_Params_Data* params =
          reinterpret_cast<internal::Page_OnRequestCompleted_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.2
      bool success = true;
      RequestPtr p_request{};
      Page_OnRequestCompleted_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadRequest(&p_request))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnRequestCompleted(        
        std::move(p_request));
      return true;
    }
  }
  return false;
}

